window.BANK=window.BANK||{};window.BANK["7236"]={"n":"第六章 学习法治思想 提升法治素养","qs":[{"i":"151577","t":"单选","q":"决定法律本质、内容和发展方向的根本因素是","o":{"A":"A.生产方式","B":"B.生产力的发展水平","C":"C.文化的发展程度","D":"D.人的素质"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P310考点42-1-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2法律由一定的社会物质生活条件所决定。</strong>物质资料生产方式既是决定社会面貌、性质和发展的根本因素，也是决定法律本质、内容和发展方向的根本因素。</span></p>\n<p>&nbsp;</p>","k":"考点33 法律的含义及其历史发展","kid":"405","r":39098,"tot":93903},{"i":"151578","t":"单选","q":"法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定(立法)、法律执行(执法)、法律适用(司法)、法律遵守(守法)等环节。法律实施和实现的基本途径是","o":{"A":"A.法律制定","B":"B.法律遵守","C":"C.法律执行","D":"D.法律适用"},"a":"B","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P311考点44-4-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2 守法是法律实施和实现的基本途径。</strong>一切组织和个人都必须遵守宪法和法律，任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>在法律运行过程中，法律遵守(守法)是法律实施和实现的基本途径。B正确。法律制定(立法)是指有立法权的国家机关依照法定职权和程序制定规范性法律文件的活动，是法律运行的起始性和关键性环节。在狭义上，法律执行(执法)是指国家行政机关及其公职人员执行法律的活动，也被称为行政执法，是法律实施和实现的重要环节。法律适用(司法)是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。A、C、D不符合题意。</p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":36992,"tot":88458},{"i":"151579","t":"单选","q":"国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动，称为","o":{"A":"A.法律执行","B":"B.法律制裁","C":"C.法律遵守","D":"D.法律适用"},"a":"D","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P311考点44-3-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1含义：</strong>法律适用是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。</span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":35811,"tot":84176},{"i":"151580","t":"单选","q":"法律的实施包括法律适用和法律执行。其中，狭义上的法律执行的主体是","o":{"A":"A.国家司法机关及其公职人员","B":"B.国家行政机关及其公职人员","C":"C.国家立法机关及其公职人员","D":"D.社会团体及其公职人员"},"a":"B","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P311考点44-2-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>5含义：在广义上，</strong>法律执行是指国家机关及其公职人员，在国家和公共事务管理中依照法定职权和程序，贯彻和实施法律的活动<strong>。在狭义上，</strong>法律执行则是指国家行政机关及其公职人员执行法律的活动，<strong>也被称为行政执法。</strong>我国大部分的法律法规都是由行政机关执行的。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>在广义上，法律执行是指国家机关及其公职人员，在国家和公共事务管理中依照法定职权和程序，贯彻和实施法律的活动。在狭义上，法律执行则是指国家行政机关及其公职人员执行法律的活动，也被称为行政执法。在我国，大部分的法律法规都是由行政机关执行的。B正确。</p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":47023,"tot":78521},{"i":"151581","t":"单选","q":"我国的法治同西方资本主义国家的法治最大的区别是","o":{"A":"A.坚持党的领导","B":"B.坚持以人民为中心","C":"C.坚持中国特色社会主义制度","D":"D.坚持中国特色社会主义法治理论"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P313考点46-3-(1)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(1)坚持中国共产党的领导</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">党的领导是中国特色社会主义<strong>最本质的特征</strong>，是社会主义法治<strong>最根本的保证。</strong>党的领导是中国特色社会主义法治之魂，是我们的法治同西方资本主义国家的法治<strong>最大的区别</strong>。坚持党的领导体现在<strong>党领导立法、保证执法、支持司法、带头守法上。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证。把党的领导贯彻到依法治国全过程和各方面，是我国社会主义法治建设的一条基本经验。我国是人民民主专政的社会主义国家，党的领导是中国特色社会主义法治之魂，是我们的法治同西方资本主义国家的法治最大的区别。A正确。</p>","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":41377,"tot":78007},{"i":"151582","t":"单选","q":"全面推进依法治国是一个系统工程，是国家治理领域一场广泛而深刻的革命，涉及立法、执法、司法、守法等各个方面，在实际工作中必须有一个总揽全局、牵引各方的总抓手。全面依法治国的总抓手是","o":{"A":"A.坚持科学立法、严格执法、公正司法、全民守法","B":"B.保障和促进社会公平正义","C":"C.建设中国特色社会主义法治体系","D":"D.坚持依法治国和以德治国相结合"},"a":"C","j":"<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>出处：肖老师精讲精练P314考点47</strong></span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\">全面依法治国的<strong>宏伟目标是建设法治中国，</strong>要以建设中国特色社会主义法治体系为总抓手，围绕保障和促进社会公平正义，坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会<strong>一体建设</strong>，坚持全面推进科学立法、严格执法、公正司法、全民守法，全面推进国家各方面工作法治化。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>1.建设中国特色社会主义法治体系(全面依法治国的总抓手)重要</strong></span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\">建设中国特色社会主义法治体系，就是要形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>1完备的法律规范体系</strong>，是中国特色社会主义法治体系的前提，是法治国家、法治政府、法治社会的制度基础。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>2高效的法治实施体系。</strong>建设高效的法治实施体系，是建设中国特色社会主义法治体系的重点。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>3严密的法治监督体系</strong>，是宪法法律有效实施的重要保障，是加强对权力运行制约和监督的迫切要求。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>4有力的法治保障体系，</strong>是全面依法治国的重要依托。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>5完善的党内法规体系，</strong>是中国特色社会主义法治体系的本质要求和重要内容。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>2.坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设</strong></span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>1依法治国、依法执政、依法行政是一个有机整体。</strong>关键在于党要坚持依法执政、各级政府要坚持依法行政。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>2法治国家、法治政府、法治社会相辅相成。</strong>法治国家是法治建设的目标，法治政府是建设法治国家的重点，法治社会是构筑法治国家的基础。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>3法治政府建设(推进全面依法治国的重点任务和主体工程)。</strong>法治政府建设，对法治国家、法治社会建设具有示范带动作用。要用法治给行政权力定规矩、划界限，规范行政决策程序，健全政府守信践诺机制，加快转变政府职能。</span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>4法治社会建设(推进全面依法治国的基础工程)。</strong>建设信仰法治、公平正义、保障权利、守法诚信、充满活力、和谐有序的社会主义法治社会，是增强人民群众获得感、幸福感、安全感的重要举措。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>全面推进依法治国涉及很多方面，在实际工作中必须有一个总揽全局、牵引各方的总抓手，这个总抓手就是建设中国特色社会主义法治体系。依法治国各项工作都要围绕这个总抓手来谋划、来推进。C正确。</p>","k":"考点38 建设法治中国","kid":"410","r":45157,"tot":75481},{"i":"151583","t":"单选","q":"建设中国特色社会主义法治体系，就是在中国共产党领导下，坚持中国特色社会主义制度，贯彻中国特色社会主义法治理论，形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。其中，建设中国特色社会主义法治体系的重点是建设","o":{"A":"A.完备的法律规范体系","B":"B.高效的法治实施体系","C":"C.有力的法治保障体系","D":"D.严密的法治监督体系"},"a":"B","j":"<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>出处：肖老师精讲精练P314考点47-1-2</strong></span></p>\n<p><span style=\"color: #000000; background-color: #bfedd2;\"><strong>2高效的法治实施体系。</strong>建设高效的法治实施体系，是建设中国特色社会主义法治体系的<strong>重点。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>完备的法律规范体系，是中国特色社会主义法治体系的前提，是法治国家、法治政府、法治社会的制度基础；建设高效的法治实施体系，是建设中国特色社会主义法治体系的重点；严密的法治监督体系，是宪法法律有效实施的重要保障；有力的法治保障体系，是全面依法治国的重要依托。B正确，A、C、D错误。</p>","k":"考点38 建设法治中国","kid":"410","r":34371,"tot":76273},{"i":"151584","t":"单选","q":"全面依法治国是一个系统工程，要整体谋划，更加注重系统性、整体性、协同性。推进全面依法治国，要坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设。其中，构筑法治国家的基础是","o":{"A":"A.法治政府","B":"B.依法执政","C":"C.法治社会","D":"D.依法行政"},"a":"C","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P314考点47-2-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2法治国家、法治政府、法治社会相辅相成。</strong>法治国家是法治建设的目标，法治政府是建设法治国家的重点，法治社会是构筑法治国家的基础。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>要坚持法治国家、法治政府、法治社会一体建设。法治国家是法治建设的目标；法治政府是建设法治国家的重点，法治政府建设是全面依法治国的重点任务和主体工程；法治社会是构筑法治国家的基础。C正确。</p>","k":"考点38 建设法治中国","kid":"410","r":45562,"tot":73029},{"i":"151585","t":"单选","q":"习近平指出，党纪国法不能成为“橡皮泥”“稻草人”,无论是因为“法盲”导致违纪违法，还是故意违规违法，都要受到追究，否则就会形成“破窗效应”。任何人不论权力大小、职位高低，只要有违法犯罪行为，就要受到法律制裁，这体现的是法律的","o":{"A":"A.普遍适用","B":"B.优先适用","C":"C.不可违反","D":"D.阶级属性"},"a":"C","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P316考点51-2-(1)-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2. 具体表现：法律的普遍适用、优先适用、不可违反。</strong>法律的普遍适用，是指法律在本国国内对所有人有效的约束力。法律要优先适用，是指当同一项社会关系同时受到多种社会规范的调整而多种社会规范又相互矛盾时，要优先考虑法律规范的适用。法律的不可违反，是指法律必须遵守，违反法律要受到惩罚。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>法律的普遍适用，是指法律在本国主权范围内对所有人具有普遍的约束力。所有国家机关、社会组织和公民个人都必须遵守法律，依法享有和行使法定职权与权利，承担和履行法定职责与义务。法律的优先适用，是指当同一项社会关系同时受到多种社会规范的调整而多种社会规范又相互矛盾时，要优先考虑法律规范的适用。法律的不可违反，是指法律必须遵守，违反法律要受到惩罚。任何人不论权力大小、职位高低，只要有违法犯罪行为，就要受到法律制裁。C正确。A、B不符合题意，D错误。</p>","k":"考点42 培养社会主义法治思维","kid":"414","r":35936,"tot":74310},{"i":"151586","t":"单选","q":"《中华人民共和国民法典》是新中国成立以来第一部以“法典”命名的法律，被誉为“保障民事权利的宣言书”。权利保障主要是指对公民权利的法律保障，具体包括公民权利的宪法保障、立法保障、行政保障和司法保障。权利保障的关键环节是","o":{"A":"A.宪法保障","B":"B.立法保障","C":"C.行政保障","D":"D.司法保障"},"a":"C","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P317考点51-2-(4)-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2内容：包括公民权利的宪法保障(权利保障的前提和基础)、立法保障(权利保障的重要条件)、行政保障(权利保障的关键环节)、司法保障(公民权利保障的最后防线)。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>宪法保障是权利保障的前提和基础。宪法表明尊重和保障人权的鲜明态度，确立保障权利的有效机制，明确列出宪法保障的公民基本权利，能够推动整个国家和法律体系加强权利保障。立法保障是权利保障的重要条件。行政保障是权利保障的关键环节。司法保障是公民权利保障的最后防线，既是解决个人之间权利纠纷的有效渠道，也是纠正和遏制行政机关侵犯公民权利的有力机制。C正确，A、B、D不符合题意。</p>","k":"考点42 培养社会主义法治思维","kid":"414","r":29939,"tot":74831},{"i":"151587","t":"单选","q":"按照程序做事情，才能防止主观任性、无序混乱。程序运行合乎法律的规定，有关机关或个人不得违反或变相违反，这是程序的","o":{"A":"A.中立性","B":"B.公开性","C":"C.参与性","D":"D.合法性"},"a":"D","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P317考点51-2-(5)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(5)程序正当</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>表现在程序的合法性、中立性、参与性、公开性、时限性等方面。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>程序正当，表现在程序的合法性、中立性、参与性、公开性、时限性等方面。合法性是指程序运行合乎法律的规定，有关机关或个人不得违反或变相违反；中立性是指程序设计和运行应平等地对待双方当事人，不得偏向任何一方；参与性是指案件或纠纷的利害关系人都有机会进入办案程序，充分表达自己的利益诉求和意见主张，为解决纠纷发挥作用；公开性是指程序运行的过程和结果应当向当事人和社会公开，以接受各方监督，防止办案不公和暗箱操作，让正义以人们看得见的方式实现。D正确，A、B、C错误。</p>","k":"考点42 培养社会主义法治思维","kid":"414","r":50800,"tot":69601},{"i":"151588","t":"单选","q":"马克思主义权利观与其他权利观的根本区别在于","o":{"A":"A.强调社会的物质生活条件对权利的制约和决定作用","B":"B.强调公民的权利和义务是平等的","C":"C.强调公民的权利和义务是统一的","D":"D.强调权利和义务关系是社会关系的核心部分"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P317考点52-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1.马克思主义权利观与其他权利观的根本区别：强调社会的物质生活条件对权利的制约和决定作用</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>马克思主义认为，权利的产生、发展和实现，都必须以一定的社会经济条件为基础。强调社会的物质生活条件对权利的制约和决定作用，这是马克思主义权利观与其他权利观的根本区别。A正确，B、C、D都不符合题意。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":37765,"tot":71221},{"i":"151589","t":"单选","q":"法律权利是指由一定的社会物质生活条件所制约的行为自由，是法律所允许的权利人为了满足自己的利益而采取的、由其他人的法律义务所保障的法律手段。法律权利区别于其他权利的根本所在是","o":{"A":"A.受社会物质生活条件的制约","B":"B.由国家强制力保障其实现","C":"C.源于现实需要","D":"D.随着历史的发展变化而变化"},"a":"B","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P317考点52-2-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">3法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性。<strong>由国家强制力保障其实现，这是法律权利区别于其他权利的根本所在。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性。由国家强制力保障其实现，这是法律权利区别于其他权利的根本所在。B正确，A、C、D都不符合题意。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":54966,"tot":67243},{"i":"151590","t":"单选","q":"我国宪法法律规定了公民享有一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。公民参加国家政治、经济与社会生活的基础是","o":{"A":"A.表达权利","B":"B.人身权利","C":"C.社会经济权利","D":"D.文化教育权利"},"a":"B","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P319考点53-3-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1.政治权利(公民参与国家政治活动的权利和自由的统称)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>重要性。</strong>公民的政治权利构成了实现人民主权原则及各种具体民主制度不可或缺的前提条件，反过来又体现了人民主权原则及各种具体民主制度的必然要求。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2内容：第一，选举权，</strong>即选举权与被选举权。<strong>第二，表达权。</strong>表达权对于一个国家的政治、经济、文化、科技、道德的发展具有基础性作用。<strong>第三，民主管理权。第四，监督权。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>人身权利是指公民的人身不受非法侵犯的权利，包括生命健康权、人身自由权、人格尊严权、住宅安全权、通信自由权等具体权利。人身权利是公民参加国家政治、经济与社会生活的基础，是公民权利的重要内容。B正确，A、C、D都不符合题意。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":47691,"tot":68417},{"i":"151591","t":"单选","q":"我国宪法法律规定了公民享有一系列权利。人享有其他各项权利的前提是","o":{"A":"A.生命权","B":"B.健康权","C":"C.人身自由权","D":"D.人格尊严权"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P319考点53-3-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2内容：第一，生命健康权。生命权是人最基本、最原始的权利，</strong>具有神圣性与不可转让性，不可非法剥夺。享有生命权是人享有其他各项权利的前提。<strong>第二，人身自由权</strong>。人身自由是人们一切行动和生活的前提条件。<strong>第三，人格尊严权。</strong>人格尊严权的基本内容有姓名权、肖像权、名誉权、荣誉权、隐私权等。<strong>第四，住宅安全权，</strong>也称住宅不受侵犯权。<strong>第五，通信自由权。</strong></span></p>\n<p><strong>简析：</strong>生命健康权是人身权利的主要内容之一。生命健康权，即维持生命存在的权利。生命权是人最基本、最原始的权利，具有神圣性与不可转让性，不可非法剥夺。享有生命权是人享有其他各项权利的前提。A正确，B、C、D错误。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":46004,"tot":67762},{"i":"151592","t":"单选","q":"“法律既不是铭刻在大理石上，也不是铭刻在铜表上，而是铭刻在公民们的内心里。”卢梭这句话强调的是","o":{"A":"A.法律必须被信仰，否则形同虚设","B":"B.要用实际行动保障法律实施","C":"C.应当拥护法律的规定，接受法律的约束","D":"D.对违法犯罪行为要敢于揭露、敢于抵制"},"a":"A","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P320考点55-1-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>必要性：法律的权威源自人民的内心拥护和真诚信仰。</strong>人民权益要靠法律保障，法律权威要靠人民维护。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>法律的权威源自人民的内心拥护和真诚信仰。人民权益要靠法律保障，法律权威要靠人民维护。尊重法律权威，就要信仰法律，对法律常怀敬畏之心。卢梭这句话强调的是法律必须被信仰，否则形同虚设。A正确。B、C、D涉及的是遵守法律、服从法律和维护法律的内容，都不符合题意。</p>","k":"考点44 不断提升法治素养","kid":"416","r":45403,"tot":67655},{"i":"151593","t":"单选","q":"法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定(立法)、法律执行(执法)、法律适用(司法)、法律遵守(守法)等环节。其中，法律运行的起始性和关键性环节是()","o":{"A":"A.法律制定","B":"B.法律执行","C":"C.法律适用","D":"D.法律遵守"},"a":"A","j":"<p>法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定(立法)、法律执行(执法)、法律适用(司法)、法律遵守(守法)等环节。<span style=\"color: #e03e2d;\">||</span>其中，<span style=\"background-color: #f8cac6; color: #000000;\">法律运行的起始性和关键性环节</span><strong>是</strong>()</p>\n<p>A.法律制定&radic;</p>\n<p>B.法律执行<span style=\"background-color: #f8cac6; color: #000000;\">行政执法是法律实施和实现的重要环节</span></p>\n<p>C.法律适用<span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>D.法律遵守<span style=\"background-color: #f8cac6; color: #000000;\">守法是法律实施和实现的基本途径</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法律运行的起始性和关键性环节是法律制定。</span></p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":45817,"tot":68020},{"i":"151594","t":"单选","q":"法律适用是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。在我国，司法机关是指国家审判机关和检察机关。司法的基本要求是()","o":{"A":"A.公正、公平、公开","B":"B.科学、民主、依法","C":"C.合法、合理、信赖保护、效率","D":"D.正确、合法、合理、及时"},"a":"D","j":"<p>法律适用是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。在我国，司法机关是指国家审判机关和检察机关。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">司法的基本要求</span><strong>是</strong>()</p>\n<p>A.公正、公平、公开<span style=\"background-color: #f8cac6; color: #000000;\">属于立法的原则</span></p>\n<p>B.科学、民主、依法<span style=\"background-color: #f8cac6; color: #000000;\">属于立法的坚持，坚持科学立法、民主立法、依法立法</span></p>\n<p>C.合法、合理、信赖保护、效率<span style=\"background-color: #f8cac6; color: #000000;\">属于行政执法的基本原则</span></p>\n<p>D.正确、合法、合理、及时&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">司法的基本要求是正确、合法、合理、及时。</span></p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":23888,"tot":71700},{"i":"151595","t":"单选","q":"法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定、法律执行、法律适用、法律遵守等环节。其中，对权利和义务即社会利益和负担进行的权威性分配的环节是()","o":{"A":"A.法律执行","B":"B.法律制定","C":"C.法律遵守","D":"D.法律适用"},"a":"B","j":"<p>法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定、法律执行、法律适用、法律遵守等环节。其中，<span style=\"background-color: #f8cac6; color: #000000;\">对权利和义务即社会利益和负担进行的权威性分配的环节</span><strong>是</strong>()</p>\n<p>A.法律执行</p>\n<p>B.法律制定&radic;</p>\n<p>C.法律遵守</p>\n<p>D.法律适用</p>\n<p><span style=\"background-color: #f8cac6; color: #000000;\">ACD:法律的执行、适用、遵守把法律规范转化为法律实践，把法定的权利和义务转化为现实的权利和义务</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">对权利和义务即社会利益和负担进行的权威性分配的环节是法律制定。</span></p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":40716,"tot":68392},{"i":"151596","t":"单选","q":"全面推进依法治国，涉及立法、执法、司法、守法等各个方面，涉及中国特色社会主义事业“五位一体”总体布局的各个领域。全面依法治国的重点是()","o":{"A":"A.科学立法","B":"B.严格执法","C":"C.公正司法","D":"D.全民守法"},"a":"C","j":"<p>全面推进依法治国，涉及立法、执法、司法、守法等各个方面，涉及中国特色社会主义事业&ldquo;五位一体&rdquo;总体布局的各个领域。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">全面依法治国的重点</span><strong>是</strong>()</p>\n<p>A.科学立法<span style=\"background-color: #f8cac6; color: #000000;\">全面依法治国的前提</span></p>\n<p>B.严格执法<span style=\"background-color: #f8cac6; color: #000000;\">全面依法治国的关键</span></p>\n<p>C.公正司法&radic;</p>\n<p>D.全民守法<span style=\"background-color: #f8cac6; color: #000000;\">全面依法治国的基础</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">公正司法，是全面依法治国的重点，是维护社会公平正义的最后一道防线。</span></p>","k":"考点38 建设法治中国","kid":"410","r":25415,"tot":72150},{"i":"151597","t":"单选","q":"法律至上是指在国家或社会的所有规范中，法律是地位最高、效力最广、强制力最大的规范。所有国家机关、社会组织和公民个人都必须遵守法律，依法享有和行使法定职权与权利，承担和履行法定职责与义务，这体现法律至上的()","o":{"A":"A.优先适用性","B":"B.不可违抗性","C":"C.公平正义性","D":"D.普遍适用性"},"a":"D","j":"<p>法律至上是指在国家或社会的所有规范中，法律是地位最高、效力最广、强制力最大的规范。<span style=\"background-color: #f8cac6; color: #000000;\">所有国家机关、社会组织和公民个人都必须遵守法律</span>，依法享有和行使法定职权与权利，承担和履行法定职责与义务，<span style=\"color: #e03e2d;\">|</span><strong>这体现法律至上的</strong>()</p>\n<p>A.优先适用性<span style=\"background-color: #f8cac6; color: #000000;\">是指多种社会规范相互矛盾时，要优先考虑法律规范的适用</span></p>\n<p>B.不可违抗性<span style=\"background-color: #f8cac6; color: #000000;\">强调只要有违法犯罪行为，就要依法追究和承担法律责任</span></p>\n<p>C.公平正义性<span style=\"background-color: #f8cac6; color: #000000;\">法律至上中无此表述</span></p>\n<p>D.普遍适用性&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">普遍适用性，是指法律在本国主权范围内对所有人具有普通约束力。</span></p>","k":"考点42 培养社会主义法治思维","kid":"414","r":39800,"tot":66989},{"i":"151598","t":"单选","q":"作为公民实现法律权利与自由的前提，整个社会共同体存在和发展的基础，以及整个法律制度存在的基础是()","o":{"A":"A.依法纳税","B":"B.维护国家统一","C":"C.依法服兵役的义务","D":"D.遵守宪法和法律"},"a":"B","j":"<p>作为公民实现法律权利与自由的前提，整个社会共同体存在和发展的基础，以及<span style=\"background-color: #f8cac6; color: #000000;\">整个法律制度存在的基础</span><strong>是</strong>()</p>\n<p>A.依法纳税</p>\n<p>B.维护国家统一&radic;</p>\n<p>C.依法服兵役的义务</p>\n<p>D.遵守宪法和法律</p>\n<p><span style=\"background-color: #f8cac6; color: #000000;\">ACD:为我国宪法规定的法律义务，但不合题意</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">作为公民实现法律权利与自由的前提，整个社会共同体存在和发展的基础，以及整个法律制度存在的基础是维护国家统一。</span></p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":33274,"tot":68368},{"i":"151599","t":"单选","q":"建设中国特色社会主义法治体系，就是在中国共产党领导下，坚持中国特色社会主义制度，形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。其中，完备的法律规范体系是()","o":{"A":"A.中国特色社会主义法治体系的重点","B":"B.中国特色社会主义法治体系的本质要求","C":"C.中国特色社会主义法治体系的重要内容","D":"D.中国特色社会主义法治体系的前提"},"a":"D","j":"<p>建设中国特色社会主义法治体系，就是在中国共产党领导下，坚持中国特色社会主义制度，形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。<span style=\"color: #e03e2d;\">|</span>其中，<span style=\"background-color: #f8cac6; color: #000000;\">完备的法律规范体系</span><strong>是</strong>()</p>\n<p>A.中国特色社会主义法治体系的重点<span style=\"background-color: #f8cac6; color: #000000;\">指的是建设高效的法治实施体系</span></p>\n<p>B.中国特色社会主义法治体系的本质要求</p>\n<p>C.中国特色社会主义法治体系的重要内容</p>\n<p><span style=\"background-color: #f8cac6; color: #000000;\">BC 指的是建设完善的党内法规体系</span></p>\n<p>D.中国特色社会主义法治体系的前提&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">完备的法律规范体系是中国特色社会主义法治体系的前提。</span></p>","k":"考点38 建设法治中国","kid":"410","r":43763,"tot":65962},{"i":"151600","t":"单选","q":"全面依法治国是一个系统工程，要整体谋划，注重系统性、整体性、协同性，必须有一个总揽全局、牵引各方的总抓手。这个总抓手就是建设中国特色社会主义法治体系。建设中国特色社会主义法治体系的重点是()","o":{"A":"A.完备的法律规范体系","B":"B.高效的法治实施体系","C":"C.有力的法治保障体系","D":"D.完善的党内法规体系"},"a":"B","j":"<p>全面依法治国是一个系统工程，要整体谋划，注重系统性、整体性、协同性，必须有一个总揽全局、牵引各方的总抓手。这个总抓手就是建设中国特色社会主义法治体系。<span style=\"background-color: #f8cac6; color: #000000;\">建设中国特色社会主义法治体系的重点</span><strong>是</strong>()</p>\n<p>A.完备的法律规范体系<span style=\"background-color: #f8cac6; color: #000000;\">中国特色社会主义法治体系的前提</span></p>\n<p>B.高效的法治实施体系&radic;</p>\n<p>C.有力的法治保障体系<span style=\"background-color: #f8cac6; color: #000000;\">全面依法治国的重要依托</span></p>\n<p>D.完善的党内法规体系<span style=\"background-color: #f8cac6; color: #000000;\">中国特色社会主义法治体系的本质要求和重要内容</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">建设中国特色社会主义法治体系的重点是高效的法治实施体系。</span></p>","k":"考点38 建设法治中国","kid":"410","r":42224,"tot":65168},{"i":"151601","t":"单选","q":"公民在行使法律权利时，不仅要在形式上符合相关法律的规定，也要符合立法意图和精神，不得违反宪法法律确定的基本原则。此外，行使权利不得破坏公序良俗，妨碍法律的社会功能和法律价值的实现。这体现的是依法行使法律权利中()","o":{"A":"A.权利行使目的的正当性的要求","B":"B.权利行使的必要限度的要求","C":"C.权利行使方式的法定性的要求","D":"D.权利行使的正当程序的要求"},"a":"A","j":"<p>公民在行使法律权利时，不仅要在形式上符合相关法律的规定，也要符合<span style=\"background-color: #f8cac6; color: #000000;\">立法意图和精神</span>，不得违反宪法法律确定的基本原则。此外，行使权利不得破坏公序良俗，妨碍法律的<span style=\"background-color: #f8cac6; color: #000000;\">社会功能和法律价值</span>的实现。<span style=\"color: #e03e2d;\">|</span>这<strong>体现的是</strong><span style=\"background-color: #f8cac6; color: #000000;\">依法行使法律权利</span><strong>中</strong>()</p>\n<p>A.权利行使目的的正当性的要求&radic;</p>\n<p>B.权利行使的必要限度的要求<span style=\"background-color: #f8cac6; color: #000000;\">强调的是限度，不合题意</span></p>\n<p>C.权利行使方式的法定性的要求<span style=\"background-color: #f8cac6; color: #000000;\">强调的是合法的方式，不合题意</span></p>\n<p>D.权利行使的正当程序的要求<span style=\"background-color: #f8cac6; color: #000000;\">强调的是程序，不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">材料体现的是依法行使法律权利中权利行使目的的正当性的要求。</span></p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":31970,"tot":66884},{"i":"151602","t":"单选","q":"法律遵守是法律运行过程中的一个环节，是指国家机关、社会组织和公民个人依照法律规定行使权力或权利以及履行职责或义务的活动。在法律运行过程中，法律实施和实现的基本途径是","o":{"A":"A.立法","B":"B.执法","C":"C.司法","D":"D.守法"},"a":"D","j":"识记点A.立法——是法律运行的起始性和关键性环节。B.执法——是法律实施和实现的重要环节。C.司法——是国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。D.守法——是法律实施和实现的基本途径，是本题正确答案。","k":"","kid":"","r":31787,"tot":66670},{"i":"151603","t":"单选","q":"法律适用是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。在我国，司法机关是指国家审判机关和检察机关。司法的基本要求是","o":{"A":"A.公正、公平、公开","B":"B.科学立法、民主立法、依法立法","C":"C.合法性、合理性、信赖保护、效率","D":"D.正确、合法、合理、及时"},"a":"D","j":"识记点A.公正、公平、公开——是立法的原则。B.科学立法、民主立法、依法立法——是立法中要贯彻执行的要求。C.合法性、合理性、信赖保护、效率——是行政执法的基本原则。D.正确、合法、合理、及时——是司法的基本要求，是本题正确答案。","k":"","kid":"","r":46624,"tot":63030},{"i":"151604","t":"单选","q":"全面依法治国是坚持和发展中国特色社会主义的本质要求和重要保障，是国家治理的一场深刻变革。全面依法治国的根本遵循是","o":{"A":"A.《中华人民共和国宪法》","B":"B.中国特色社会主义法治道路","C":"C.习近平法治思想","D":"D.社会主义核心价值观"},"a":"C","j":"识记点A.《中华人民共和国宪法》——是国家各项制度和法律法规的总依据。B.中国特色社会主义法治道路——是社会主义法治建设成就和经验的集中体现，是建设社会主义法治国家的唯一正确道路。C.习近平法治思想——是全面依法治国的指导思想和根本遵循，是本题正确答案。D.社会主义核心价值观——是坚持和发展中国特色社会主义的价值遵循。","k":"","kid":"","r":22120,"tot":68153},{"i":"151605","t":"单选","q":"既是社会主义法律的基本属性，又是社会主义法治的基本要求的是","o":{"A":"A.诚信","B":"B.平等","C":"C.民主","D":"D.公正"},"a":"B","j":"<p>识记点A.诚信&mdash;&mdash;是社会主义核心价值观的一条重要准则。B.平等&mdash;&mdash;是社会主义法律的基本属性，是社会主义法治的基本要求，是本题正确答案。C.民主&mdash;&mdash;是人民当家作主，人民民主是社会主义的生命。D.公正&mdash;&mdash;是法治的生命线，是司法活动最高的价值追求。</p>","k":"","kid":"","r":21713,"tot":68637},{"i":"151606","t":"单选","q":"既是中国特色社会主义法治体系的前提，又是法治国家、法治政府、法治社会的制度基础的是","o":{"A":"A.法律实施","B":"B.完备的法律规范体系","C":"C.公正司法","D":"D.《中华人民共和国宪法》"},"a":"B","j":"识记点A.法律实施——是法律的生命力所在，是法律的权威所在。B.完备的法律规范体系——是中国特色社会主义法治体系的前提，是法治国家、法治政府、法治社会的制度基础，是本题正确答案。C.公正司法——是维护社会公平正义的最后一道防线。D.《中华人民共和国宪法》——是国家的根本法，是党和人民意志的集中体现。","k":"","kid":"","r":43244,"tot":63615},{"i":"151607","t":"单选","q":"建设中国特色社会主义法治体系，就是要形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。其中，中国特色社会主义法治体系的本质要求和重要内容是","o":{"A":"A.建设高效的法治实施体系","B":"B.建设完善的党内法规体系","C":"C.严密的法治监督体系","D":"D.有力的法治保障体系"},"a":"B","j":"识记点A.建设高效的法治实施体系——是建设中国特色社会主义法治体系的重点。B.建设完善的党内法规体系——是中国特色社会主义法治体系的本质要求和重要内容，是本题正确答案。C.严密的法治监督体系——是宪法法律有效实施的重要保障，是加强对权力运行制约和监督的迫切要求。D.有力的法治保障体系——是全面依法治国的重要依托。","k":"","kid":"","r":28367,"tot":66504},{"i":"151608","t":"单选","q":"习近平总书记指出，法治国家、法治政府、法治社会三者各有侧重、相辅相成。构筑法治国家的基础是","o":{"A":"A.法治政府","B":"B.依法治国","C":"C.法治社会","D":"D.科学立法"},"a":"C","j":"识记点A.法治政府——是建设法治国家的重点。B.依法治国——是党领导人民治理国家的基本方略。C.法治社会——是构筑法治国家的基础，是本题正确答案。D.科学立法——是全面依法治国的前提。","k":"","kid":"","r":43149,"tot":62557},{"i":"151609","t":"单选","q":"全面依法治国，必须从立法、执法、司法、守法四个方面统筹推进。全面依法治国的关键是","o":{"A":"A.科学立法","B":"B.严格执法","C":"C.公正司法","D":"D.全民守法"},"a":"B","j":"<p>识记点A.科学立法&mdash;&mdash;是全面依法治国的前提，立法是法治的龙头环节。B.严格执法&mdash;&mdash;是全面依法治国的关键，是本题正确答案。C.公正司法&mdash;&mdash;是全面依法治国的重点，是维护社会公平正义的最后一道防线。D.全民守法&mdash;&mdash;是全面依法治国的基础，是法治社会的基础工程。</p>","k":"","kid":"","r":32283,"tot":65790},{"i":"151610","t":"单选","q":"法律权利是指由一定的社会物质生活条件所制约的行为自由，是法律所允许的权利人为了满足自己的利益而采取的、由其他人的法律义务所保障的法律手段。权利的产生、发展和实现，都必须以一定的社会经济条件为基础。法律权利区别于其他权利的根本所在是","o":{"A":"A.法律权利的内容、种类和实现程度受社会物质生活条件的制约","B":"B.法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异","C":"C.由国家强制力保障其实现","D":"D.法律权利必须依法行使"},"a":"C","j":"识记点A、B、D选项的说法——是法律权利的特征，并不是法律权利区别于其他权利的根本所在。C.由国家强制力保障其实现——是法律权利区别于其他权利的根本所在，是本题正确答案。","k":"","kid":"","r":44256,"tot":62106},{"i":"151611","t":"单选","q":"法律义务的履行表现为两种形式，包括","o":{"A":"A.作为和不作为","B":"B.履行和不履行","C":"C.执行和不执行","D":"D.积极和不积极"},"a":"A","j":"识记点A.作为和不作为——是法律义务履行的两种表现形式，是本题正确答案。B、C、D选项的说法——非考点。","k":"","kid":"","r":29840,"tot":64977},{"i":"151612","t":"多选","q":"法律是由国家创制和实施的行为规范。法律不但由国家制定和认可，而且由国家强制力保证实施。也就是说，法律具有国家强制性。法律的国家强制性表现为","o":{"A":"A.国家对违法行为的否定和制裁","B":"B.国家对合法行为的肯定和保护","C":"C.法律的每一个实施过程都要借助于国家的强制力","D":"D.国家强制力是保证法律实施的唯一力量"},"a":"AB","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P310考点42-1-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>法律是由国家创制和实施的行为规范。法律不但由国家制定和认可，而且由国家强制力保证实施。</strong>也就是说，法律具有国家强制性，这既表现为国家对合法行为的肯定和保护，也表现为国家对违法行为的否定和制裁。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>法律的国家强制性，既表现为国家对违法行为的否定和制裁，也表现为国家对合法行为的肯定和保护。A、B正确。国家强制力并不是保证法律实施的唯一力量，法律意识、道德观念、价值观念、纪律观念也在保证法律的实施过程中发挥着重要作用，C、D错误。</p>","k":"考点33 法律的含义及其历史发展","kid":"405","r":31790,"tot":62504},{"i":"151613","t":"多选","q":"法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定(立法)、法律执行(执法)、法律适用(司法)、法律遵守(守法)等环节。其中，把法律规范转化为法律实践，把法定的权利和义务转化为现实的权利和义务是法律运行环节中的","o":{"A":"A.法律制定","B":"B.法律执行","C":"C.法律适用","D":"D.法律遵守"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P311考点44 考点我国社会主义法律的运行</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定(立法)、法律执行(执法)、法律适用(司法)、法律遵守(守法)等环节。</strong>法律制定是国家对权利和义务，即社会利益和负担进行的权威性分配；法律的执行、适用、遵守则是把法律规范转化为法律实践，把法定的权利和义务转化为现实的权利和义务。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1.法律制定(法律运行的起始性和关键性环节)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>含义</strong>：法律制定是指有立法权的国家机关依照法定职权和程序制定规范性法律文件的活动。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>原则：贯彻公正、公平、公开原则，</strong>坚持科学立法、民主立法、依法立法。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>法定程序</strong>：就全国人民代表大会的立法程序而言，包括法律案的提出、法律案的审议、法律案的表决、法律的公布四个环节。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.法律执行(行政执法是法律实施和实现的重要环节)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>含义</strong>：在广义上，法律执行是指国家机关及其公职人员，在国家和公共事务管理中依照法定职权和程序，贯彻和实施法律的活动。在狭义上，法律执行则是指国家行政机关及其公职人员执行法律的活动，也被称为行政执法。我国大部分的法律法规都是由行政机关执行的。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>行政执法的基本原则：合法性、合理性、信赖保护、效率等。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>行政执法的两类主体：</strong>一类是中央和地方各级政府，包括国务院和地方各级人民政府；另一类是各级政府中享有执法权的下属行政机构。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3.法律适用(司法)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>含义</strong>：法律适用是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>我国的司法机关</strong>：国家审判机关和检察机关。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>司法的基本要求</strong>：正确、合法、合理、及时。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">④<strong>司法的原则</strong>：司法公正；公民在法律面前一律平等；以事实为根据，以法律为准绳；司法机关依法独立公正行使司法权等。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>4.法律遵守(依法办事，即守法)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>含义</strong>：法律遵守是指国家机关、社会组织和公民个人依照法律规定行使权力或权利以及履行职责或义务的活动。守法就是依法享有并行使权利、依法承担并履行义务。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>守法是法律实施和实现的基本途径。</strong>一切组织和个人都必须遵守宪法和法律，任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定(立法)、法律执行(执法)、法律适用(司法)、法律遵守(守法)等环节。法律制定是国家对权利和义务，即社会利益和负担进行的权威性分配；法律的执行、适用、遵守则是把法律规范转化为法律实践，把法定的权利和义务转化为现实的权利和义务。B、C、D正确，A错误。</p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":26563,"tot":63321},{"i":"151614","t":"多选","q":"我国大部分的法律法规都是由行政机关执行的。行政执法是法律实施和实现的重要环节，必须坚持的基本原则有","o":{"A":"A.合法性","B":"B.合理性","C":"C.信赖保护","D":"D.效率"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P311考点44-2-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>行政执法的基本原则：合法性、合理性、信赖保护、效率等。</strong></span></p>\n<p>&nbsp;</p>","k":"考点35 我国社会主义法律的运行","kid":"407","r":30082,"tot":62254},{"i":"151615","t":"多选","q":"习近平法治思想系统阐述了全面依法治国的政治方向、战略地位、工作布局、主要任务、重大关系、重要保障等。其中，科学指明了中国特色社会主义法治的前进方向的是","o":{"A":"A.坚持党对全面依法治国的领导","B":"B.坚持以人民为中心","C":"C.坚持中国特色社会主义法治道路","D":"D.坚持依宪治国、依宪执政"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P312考点45-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.习近平法治思想的主要内容</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">习近平法治思想的<strong>主要内容就是&ldquo;十一个坚持&rdquo;</strong>。其中，<strong>前3个坚持是习近平法治思想指明的政治方向</strong>，回答全面依法治国由谁领导、依靠谁、走什么道路等问题。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>坚持党对全面依法治国的领导。</strong>党的领导是推进全面依法治国的根本保证。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>坚持以人民为中心。</strong>推进全面依法治国，根本目的是依法保障人民权益。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>坚持中国特色社会主义法治道路。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">④<strong>坚持</strong>依宪治国、依宪执政。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑤<strong>坚持</strong>在法治轨道上推进国家治理体系和治理能力现代化。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑥<strong>坚持</strong>建设中国特色社会主义法治体系。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑦<strong>坚持</strong>依法治国、依法执政、依法行政共同推进，法治国家、法治政府、法治社会一体建设。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑧<strong>坚持</strong>全面推进科学立法、严格执法、公正司法、全民守法。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑨<strong>坚持</strong>统筹推进国内法治和涉外法治。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑩<strong>坚持</strong>建设德才兼备的高素质法治工作队伍。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">⑪<strong>坚持</strong>抓住领导干部这个&ldquo;关键少数&rdquo;。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>习近平法治思想系统阐述了全面依法治国的政治方向、战略地位、工作布局、主要任务、重大关系、重要保障等，涉及的都是全面依法治国方向性、根本性、全局性的重大问题，构成了习近平法治思想的主要内容。关于政治方向，这一思想深刻回答了全面依法治国由谁领导、依靠谁、走什么道路等大是大非问题，科学指明了中国特色社会主义法治的前进方向。A、B、C正确，D不符合题意。</p>\n<p><strong>点拨：</strong>习近平法治思想的核心要义，2023年版教材的提法是2020年中央全面依法治国工作会议提出的&ldquo;十一个坚持&rdquo;,《习近平法治思想学习纲要(2025年版)》的提法为&ldquo;十二个坚持&rdquo;,其核心变化是新增&ldquo;坚持依法治国和依规治党有机统一&rdquo;作为第十二个坚持，第五个坚持由&ldquo;坚持在法治轨道上推进国家治理体系和治理能力现代化&rdquo;修改为&ldquo;坚持在法治轨道上全面建设社会主义现代化国家&rdquo;。</p>","k":"考点36 全面依法治国的根本遵循——习近平法治思想","kid":"408","r":18738,"tot":65092},{"i":"151616","t":"多选","q":"习近平强调：“改革和法治如鸟之两翼、车之两轮。”改革的“破”和“变”,与法治的“立”和“稳”,只有相辅相成才能相得益彰。耕好改革“试验田”,需要把在法治轨道上推进改革和在改革进程中完善法治有机结合起来，发挥好立法引导、推动、规范、保障改革的“稳定器”作用。为此，要做到","o":{"A":"A.立法主动适应改革需要，确保改革于法有据","B":"B.实践证明行之有效的举措和经验，应及时上升为法律法规","C":"C.对不适应改革要求的现行法律法规，能修改的则及时修改，宜废止的则及时废止","D":"D.改革创新要大胆试、大胆闯，相关立法活动不受法定程序限制"},"a":"ABC","j":"<p>时政储备题</p>\n<p><strong>简析：</strong>耕好改革&ldquo;试验田&rdquo;,需要把在法治轨道上推进改革和在改革进程中完善法治有机结合起来，发挥好立法引导、推动、规范、保障改革的&ldquo;稳定器&rdquo;作用。立法主动适应改革需要，确保改革于法有据，改革创新大胆试、大胆闯、自主改就更有底气。实践证明行之有效的举措和经验，也应及时上升为法律法规。耕好改革&ldquo;试验田&rdquo;,立法工作除了要做好&ldquo;加法&rdquo;,还要做好&ldquo;减法&rdquo;。对不适应改革要求的现行法律法规，能修改的则及时修改，宜废止的则及时废止。防止不合时宜的法规条款束缚改革步伐、迟滞改革进程，有助于增强改革决心、排除改革阻力、巩固改革成果。A、B、C正确。</p>\n<p>我国立法贯彻公正、公平、公开原则，坚持科学立法、民主立法、依法立法，表达人民的共同意志和诉求。立法活动必须遵循法定程序。就全国人民代表大会的立法程序而言，大体包括法律案的提出、法律案的审议、法律案的表决和法律的公布四个环节。D错误。</p>","k":"考点36 全面依法治国的根本遵循——习近平法治思想","kid":"408","r":44215,"tot":58159},{"i":"151617","t":"多选","q":"把党的领导贯彻到依法治国全过程和各方面，是我国社会主义法治建设的一条基本经验。我国是人民民主专政的社会主义国家，党的领导是","o":{"A":"A.全面依法治国的关键","B":"B.社会主义法治最根本的保证","C":"C.中国特色社会主义法治之魂","D":"D.我们的法治同西方资本主义国家的法治最大的区别"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P313考点46-3-(1)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(1)坚持中国共产党的领导</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">党的领导是中国特色社会主义<strong>最本质的特征</strong>，是社会主义法治<strong>最根本的保证</strong>。党的领导是中国特色社会主义<strong>法治之魂</strong>，是我们的法治同西方资本主义国家的法治<strong>最大的区别</strong>。坚持党的领导体现在党<strong>领导立法、保证执法、支持司法、带头守法上。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证。把党的领导贯彻到依法治国全过程和各方面，是我国社会主义法治建设的一条基本经验。我国是人民民主专政的社会主义国家，党的领导是中国特色社会主义法治之魂，是我们的法治同西方资本主义国家的法治最大的区别。B、C、D正确。严格执法是全面依法治国的关键，A错误。</p>","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":19073,"tot":64280},{"i":"151618","t":"多选","q":"中国特色社会主义法治道路的一个鲜明特点，就是坚持依法治国和以德治国相结合。坚持依法治国和以德治国相结合，就要","o":{"A":"A.运用法治手段解决道德领域突出问题","B":"B.强化道德对法治的支撑作用","C":"C.在立法、执法、司法中都体现社会主义道德要求","D":"D.让思想道德和法律在调节领域上保持完全一致"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P313考点46-3-(4)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>(4)坚持依法治国和以德治国相结合</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">坚持依法治国和以德治国相结合，<strong>既要强化道德对法治的支撑作用，重视发挥道德的教化作用</strong>，提高全社会文明程度，为全面依法治国创造良好环境；<strong>又要把道德要求贯彻到法治建设中，以法治承载道德理念。</strong>立法、执法、司法都要体现社会主义道德要求，都要把社会主义核心价值观贯穿其中，使社会主义法治成为良法善治，引导全社会崇德向善。要运用法治手段解决道德领域突出问题，依法加强对群众反映强烈的失德行为的整治。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>坚持依法治国和以德治国相结合，既要强化道德对法治的支撑作用，重视发挥道德的教化作用，提高全社会文明程度，为全面依法治国创造良好环境；又要把道德要求贯彻到法治建设中，以法治承载道德理念。立法、执法、司法都要体现社会主义道德要求，都要把社会主义核心价值观贯穿其中，使社会主义法治成为良法善治，引导全社会崇德向善。要运用法治手段解决道德领域突出问题，依法加强对群众反映强烈的失德行为的整治。A、B、C正确。</p>\n<p>思想道德和法律都是调节人们思想行为、协调人际关系、维护社会秩序的重要手段。思想道德和法律虽然在调节领域、调节方式、调节目标等方面存在很大不同，但是二者都是上层建筑的重要组成部分，共同服务于一定的经济基础。D错误。</p>","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":38684,"tot":58721},{"i":"151619","t":"多选","q":"坚持全面依法治国，是中国特色社会主义国家制度和国家治理体系的显著优势。我国社会主义法治凝聚着我们党治国理政的理论成果和实践经验，是制度之治最基本最稳定最可靠的保障。法治兴则国兴，法治强则国强。法治是","o":{"A":"A.解决一切问题的总钥匙","B":"B.治国理政的基本方式","C":"C.国家治理体系和治理能力的重要依托","D":"D.国家核心竞争力的重要内容"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P172 考点62全面依法治国是国家治理的一场深刻革命(重要性)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①法律是治国之重器，<strong>法治是国家治理体系和治理能力的重要依托。</strong>全面依法治国是国家治理的一场深刻革命，<strong>关系</strong>党执政兴国，<strong>关系</strong>人民幸福安康，<strong>关系</strong>党和国家长治久安。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②全面依法治国，是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化的<strong>重要方面</strong>，是坚持和发展中国特色社会主义的<strong>本质要求和重要保障。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>法治是治国理政的基本方式，是国家治理体系和治理能力的重要依托。法治是国家核心竞争力的重要内容。法治兴则国兴，法治强则国强。坚持全面依法治国，是中国特色社会主义国家制度和国家治理体系的显著优势。实践充分证明，我国社会主义法治凝聚着我们党治国理政的理论成果和实践经验，是制度之治最基本最稳定最可靠的保障。B、C、D正确。习近平主席在金砖国家领导人第十二次会晤上的讲话中指出：&ldquo;我们要坚持民生优先，推进全球可持续发展。发展是解决一切问题的总钥匙。&rdquo;A错误。</p>","k":"考点38 建设法治中国","kid":"410","r":31152,"tot":60721},{"i":"151620","t":"多选","q":"每一条法治道路底下都有一种政治立场，每一种法治模式当中都有一种政治逻辑。中国特色社会主义法治道路的核心要义，就是要","o":{"A":"A.坚持党的领导","B":"B.坚持以人民为中心","C":"C.坚持中国特色社会主义制度","D":"D.贯彻中国特色社会主义法治理论"},"a":"ACD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P313考点46-1-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.为什么要走中国特色社会主义法治道路</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>走中国特色社会主义法治道路，是历史的必然结论。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>走中国特色社会主义法治道路，是由我国社会主义国家性质决定的。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>走中国特色社会主义法治道路，是立足我国基本国情的必然选择。</strong>中国特色社会主义法治道路的一个<strong>鲜明特点，就是坚持依法治国和以德治国相结合。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>中国特色社会主义法治道路的核心要义，就是要坚持党的领导，坚持中国特色社会主义制度，贯彻中国特色社会主义法治理论，这充分体现了我国社会主义性质，具有鲜明的中国特色、实践特色、时代特色。A、C、D正确，B不符合题意。</p>","k":"考点38 建设法治中国","kid":"410","r":15137,"tot":63915},{"i":"151621","t":"多选","q":"党的十八届四中全会提出和确立了建设中国特色社会主义法治体系、建设社会主义法治国家的总目标，开启了建设社会主义法治国家的新征程。建设中国特色社会主义法治体系就是要形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。完备的法律规范体系是","o":{"A":"A.中国特色社会主义法治体系的前提","B":"B.法治国家、法治政府、法治社会的制度基础","C":"C.宪法法律有效实施的重要保障","D":"D.全面依法治国的重要依托"},"a":"AB","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P314考点47-1-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>完备的法律规范体系，</strong>是中国特色社会主义法治体系的<strong>前提</strong>，是法治国家、法治政府、法治社会的<strong>制度基础</strong>。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>完备的法律规范体系，是中国特色社会主义法治体系的前提，是法治国家、法治政府、法治社会的制度基础。A、B正确。</p>\n<p>建设高效的法治实施体系，是建设中国特色社会主义法治体系的重点。严密的法治监督体系，是宪法法律有效实施的重要保障，是加强对权力运行制约和监督的迫切要求。有力的法治保障体系，是全面依法治国的重要依托。建设完善的党内法规体系，是中国特色社会主义法治体系的本质要求和重要内容。C、D错误。</p>","k":"考点38 建设法治中国","kid":"410","r":18439,"tot":64027},{"i":"151622","t":"多选","q":"“100-1=0”。“一个错案的负面影响足以摧毁99个公正裁判积累起来的良好形象。执法司法中万分之一的失误，对当事人就是百分之百的伤害。”党的二十大报告指出，要严格公正司法，深化司法体制综合配套改革，全面准确落实司法责任制，加快建设公正高效权威的社会主义司法制度，努力让人民群众在每一个司法案件中感受到公平正义。公正是","o":{"A":"A.法治的生命线","B":"B.司法活动最高的价值追求","C":"C.全面依法治国的前提","D":"D.社会主义法治最根本的保证"},"a":"AB","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P315考点47-3-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>公正司法</strong>(全面依法治国的<strong>重点</strong>)。公正是法治的<strong>生命线</strong>，是司法活动<strong>最高的价值追求</strong>。公正司法是维护社会公平正义的<strong>最后一道防线。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>公正是法治的生命线，是司法活动最高的价值追求。公正司法是维护社会公平正义的最后一道防线。A、B正确。科学立法是全面依法治国的前提，公正司法是全面依法治国的重点。C错误。党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证。D错误。</p>","k":"考点38 建设法治中国","kid":"410","r":25935,"tot":61457},{"i":"151623","t":"多选","q":"《中华人民共和国宪法》规定，国家工作人员就职时应当依照法律规定公开进行宪法宣誓。习近平指出，宪法宣誓制度有利于彰显宪法权威，增强公职人员宪法观念，激励公职人员忠于和维护宪法，也有利于在全社会增强宪法意识、树立宪法权威。把宪法放到如此重要的地位，是因为宪法","o":{"A":"A.是国家的根本法、是党和人民意志的集中体现","B":"B.是国家各项制度和法律法规的总依据","C":"C.规定了国家的根本制度","D":"D.具有最高的法律地位、法律权威、法律效力"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P315考点49-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>1.我国宪法的地位：宪法至上</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">宪法至上地位主要体现在其特有的作用、效力和内容等方面。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>我国宪法是国家的根本法，是党和人民意志的集中体现，</strong>具有显著优势、坚实基础、强大生命力(从宪法的作用看)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>我国宪法是国家各项制度和法律法规的总依据</strong>(从宪法的效力看)。宪法在中国特色社会主义法律体系中居于核心地位。我国宪法具有最高的法律地位、法律权威、法律效力，具有根本性、全局性、稳定性、长期性。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>我国宪法规定了国家的根本制度</strong>(从宪法的内容看)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">④宪法是实现国家认同、凝聚社会共识、促进个人发展的基本准则，是维系一个国家、一个民族凝聚力的<strong>根本纽带。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>我国宪法是国家的根本法，是党和人民意志的集中体现。我国宪法是国家各项制度和法律法规的总依据。宪法在中国特色社会主义法律体系中居于核心地位。我国宪法具有最高的法律地位、法律权威、法律效力，具有根本性、全局性、稳定性、长期性。我国宪法规定了国家的根本制度，确立了中国共产党的领导地位，规定了国家的根本任务、领导核心、指导思想、基本原则、发展道路、奋斗目标。A、B、C、D全选。</p>","k":"考点40 我国宪法的地位和基本原则","kid":"412","r":37108,"tot":58044},{"i":"151624","t":"多选","q":"法律至上是法治思维的基本内容之一。法律至上，具体表现为","o":{"A":"A.法律的普遍适用","B":"B.法律的优先适用","C":"C.法律的权利保障","D":"D.法律的不可违反"},"a":"ABD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P316考点51-2-(1)-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>具体表现：法律的普遍适用、优先适用、不可违反。</strong>法律的<strong>普遍适用</strong>，是指法律在本国主权范围内对所有人具有普遍的约束力。法律的<strong>优先适用</strong>，是指当同一项社会关系同时受到多种社会规范的调整而多种社会规范又相互矛盾时，要优先考虑法律规范的适用。法律的<strong>不可违反</strong>，是指法律必须遵守，违反法律要受到惩罚。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>法律至上具体表现为法律的普遍适用、优先适用和不可违反。A、B、D正确。法治思维主要包括法律至上、权力制约、公平正义、权利保障、程序正当等内容，C错误。</p>","k":"考点42 培养社会主义法治思维","kid":"414","r":24316,"tot":60206},{"i":"151625","t":"多选","q":"公平正义是法治思维的基本内容之一。公平正义主要包括权利公平、机会公平、规则公平和救济公平。权利公平包括","o":{"A":"A.权利和义务对等","B":"B.权利主体平等","C":"C.享有的权利特别是基本权利平等","D":"D.权利保护和权利救济平等"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P317考点51-2-(3)-②</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>内容：权利公平、机会公平、规则公平、救济公平。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>权利公平包括三重含义</strong>：<strong>一是</strong>权利主体平等，国家对每个权利主体&ldquo;不偏袒&rdquo;&ldquo;非歧视&rdquo;<strong>;二是</strong>享有的权利特别是基本权利平等；<strong>三是</strong>权利保护和权利救济平等。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>机会公平是指</strong>生活在同一社会中的成员拥有相同的发展机会和发展前景，反对任何形式的歧视。<strong>机会公平包括</strong>国家和社会要积极为社会成员的发展创造条件，并努力创造平等的起点(起点平等);社会成员的发展进步权要受到同等尊重，不断拓展社会成员的发展领域(发展平等);不仅要关注当代人的机会平等，还要考虑后代人的机会平等(代际平等)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>规则公平是指</strong>对所有人适用同一的规则和标准，不得因人而异。<strong>规则公平包括法律规则面前人人平等、法律内容面前人人平等和法律保护面前人人平等</strong>，任何人不得享有法律之外的特权，任何人也不会被法律排除在保护之外。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>救济公平是指</strong>为权利受到侵害或处于弱势地位的公民提供平等有效的救济。<strong>救济公平包括司法救济公平、行政救济公平、社会救济公平。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>公平正义是指社会的政治利益、经济利益和其他利益在全体社会成员之间合理、公平分配和占有。一般来讲，公平正义主要包括权利公平、机会公平、规则公平和救济公平。权利公平包括三重含义：一是权利主体平等，国家对每个权利主体&ldquo;不偏袒&rdquo;&ldquo;非歧视&rdquo;;二是享有的权利特别是基本权利平等；三是权利保护和权利救济平等。B、C、D正确，A错误。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":24988,"tot":60726},{"i":"151626","t":"多选","q":"公平正义是法治思维的基本内容之一。公平正义主要包括权利公平、机会公平、规则公平和救济公平。机会公平包括","o":{"A":"A.起点平等","B":"B.结果平等","C":"C.发展平等","D":"D.代际平等"},"a":"ACD","j":"<p><strong>简析：</strong>机会公平是指生活在同一社会中的成员拥有相同的发展机会和发展前景，反对任何形式的歧视。机会公平包括：①起点平等：国家和社会要积极为社会成员的发展创造条件，并努力创造平等的起点；②发展平等：社会成员的发展进步权要受到同等尊重，不断拓展社会成员的发展领域；③代际平等：不仅要关注当代人的机会平等，还要考虑后代人的机会平等。A、C、D正确，B错误。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":31061,"tot":58452},{"i":"151627","t":"多选","q":"权利保障是法治思维的基本内容之一。权利保障主要是指对公民权利的法律保障，具体包括公民权利的","o":{"A":"A.宪法保障","B":"B.立法保障","C":"C.行政保障","D":"D.司法保障"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P317考点51-2-(4)-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>内容：</strong>包括公民权利的<strong>宪法保障</strong>(权利保障的前提和基础)、<strong>立法保障</strong>(权利保障的重要条件)、<strong>行政保障</strong>(权利保障的关键环节)、<strong>司法保障</strong>(公民权利保障的最后防线)。</span></p>\n<p>&nbsp;</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":28931,"tot":59435},{"i":"151628","t":"多选","q":"法律权利具有的特征有","o":{"A":"A.法律权利的内容、种类和实现程度受社会物质生活条件的制约","B":"B.法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异","C":"C.法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性","D":"D.法律权利必须依法行使，不能不择手段地行使法律权利"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P317~318考点52-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.法律权利的特征(4个)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>法律权利的内容、种类和实现程度受社会物质生活条件的制约。</strong>不能脱离一个国家或地区的经济社会发展阶段和水平空谈权利及其实现。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异。</strong>同样一种权利，在不同的社会制度下和不同的国家法律中表现形式有所不同。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性。<strong>由国家强制力保障其实现，这是法律权利区别于其他权利的根本所在。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">④<strong>法律权利必须依法行使，不能不择手段地行使法律权利。</strong></span></p>\n<p>&nbsp;</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":44475,"tot":55680},{"i":"151629","t":"多选","q":"义务与权利相对应，是指政治上、法律上、道义上应当承担的责任。法律义务具有的特点有","o":{"A":"A.法律义务是历史的","B":"B.法律义务源于现实需要","C":"C.法律义务必须依法设定","D":"D.法律义务可能发生变化"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P318考点52-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3.法律义务的特点(4个)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>法律义务是历史的。</strong>法律义务的内容和履行方式随着经济社会的发展和人权保障的进步而不断调整和变化。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>法律义务源于现实需要。</strong>一个国家或地区的制度性质、历史传统、文化背景、宗教信仰和安全形势等因素，会对法律义务的设定产生重要影响。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">③<strong>法律义务必须依法设定。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">④<strong>法律义务可能发生变化。</strong>公民和社会组织承担的法律义务，在履行的过程中可能会基于法定情形而变更、消灭，或产生新的法律义务。</span></p>\n<p>&nbsp;</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":30420,"tot":58006},{"i":"151630","t":"多选","q":"人身自由是人们一切行动和生活的前提条件。人身自由是指","o":{"A":"A.人的身体不受拘束","B":"B.人的行动自由","C":"C.人身自由不受非法限制和剥夺","D":"D.公民居住、生活、休息的场所不受非法侵入或搜查的权利"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P319考点53-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>3.人身权利(公民的人身不受非法侵犯的权利)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①<strong>重要性。</strong>人身权利是公民参加国家政治、经济与社会生活的<strong>基础</strong>，是公民权利的<strong>重要内容</strong>。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">②<strong>内容：第一，生命健康权。生命权是人最基本、最原始的权利</strong>，具有神圣性与不可转让性，不可非法剥夺。享有生命权是人享有其他各项权利的前提。<strong>第二，人身自由权。人身自由是人们一切行动和生活的前提条件。第三，人格尊严权。</strong>人格尊严权的基本内容有姓名权、肖像权、名誉权、荣誉权、隐私权等。<strong>第四，住宅安全权，</strong>也称住宅不受侵犯权。<strong>第五，通信自由权。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>人身自由是人们一切行动和生活的前提条件。人身自由，首先是指人的身体不受拘束，因而被视为&ldquo;最小限度的自由&rdquo;。其次是指人的行动自由，如可以自由外出旅游、经商、打工、求学等。最后是指人身自由不受非法限制和剥夺。A、B、C正确。公民居住、生活、休息的场所不受非法侵入或搜查的权利属于住宅安全权利。D错误。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":23400,"tot":58894},{"i":"151631","t":"多选","q":"我国宪法法律规定了公民享有的一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。社会经济权利主要包括","o":{"A":"A.劳动权和休息权","B":"B.私有财产权","C":"C.社会保障权","D":"D.物质帮助权"},"a":"ACD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P319考点53-5</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>5.社会经济权利</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第一，劳动权</strong>，即一切有劳动能力的公民有获得劳动的机会和适当的劳动条件和报酬的权利。劳动权是公民赖以生存的<strong>基础</strong>，是行使其他权利的<strong>物质保障</strong>。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第二，休息权</strong>，即劳动者在付出一定的劳动以后所享有的休息和休养的权利。休息权是劳动权存在和发展的基础。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第三，社会保障权</strong>(如退休人员生活受到国家和社会的保障)。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第四，物质帮助权</strong>(如社会保险、社会救济等)。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>社会经济权利，是指公民要求国家根据社会经济的发展状况，积极采取措施干预社会经济生活，加强社会建设，提供社会服务，以促进公民的自由和幸福，保障公民过上健康而有尊严的生活的权利。社会经济权利主要包括以下几方面内容：一是劳动权；二是休息权；三是社会保障权；四是物质帮助权。A、C、D正确。财产权主要包括以下几方面内容：一是私有财产权，即公民个人所有的以财产利益为内容，直接体现财产利益的民事权利；二是继承权，是指继承人依法取得被继承人遗产的资格。B错误。</p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":20178,"tot":60539},{"i":"151632","t":"多选","q":"尊重法律权威的基本要求是","o":{"A":"A.信仰法律","B":"B.遵守法律","C":"C.服从法律","D":"D.维护法律"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P320考点55-1-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>基本要求：信仰法律、遵守法律、服从法律、维护法律。</strong></span></p>\n<p>&nbsp;</p>","k":"考点44 不断提升法治素养","kid":"416","r":41849,"tot":56162},{"i":"151633","t":"多选","q":"我国社会主义法律，是在中国共产党领导新民主主义革命时期孕育、在中华人民共和国成立后不断形成和发展起来的。我国社会主义法律的本质特征在于()","o":{"A":"A.体现了党的主张和人民意志的统一","B":"B.具有科学性和先进性","C":"C.法律会随着私有制、阶级和国家的消亡而消亡","D":"D.我国社会主义法律是中国特色社会主义建设的重要保障"},"a":"ABD","j":"<p>我国社会主义法律，是在中国共产党领导新民主主义革命时期孕育、在中华人民共和国成立后不断形成和发展起来的。<span style=\"color: #e03e2d;\">|</span>我国社会主义法律的<span style=\"background-color: #f8cac6; color: #000000;\">本质特征</span><strong>在于</strong>()</p>\n<p>A.体现了党的主张和人民意志的统一&radic;</p>\n<p>B.具有科学性和先进性&radic;</p>\n<p>C.法律会随着私有制、阶级和国家的消亡而消亡<span style=\"background-color: #f8cac6; color: #000000;\">这不是本质特征，而是法律的历史发展</span></p>\n<p>D.我国社会主义法律是中国特色社会主义建设的重要保障&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">我国社会主义法律的本质特征在于体现了党的主张和人民意志的统一(从意志来看的本质特征),具有科学性和先进性(从内容来看的本质特征),我国社会主义法律是中国特色社会主义建设的重要保障(从作用来看的本质特征)。</span></p>","k":"考点34 我国社会主义法律的本质特征","kid":"406","r":41416,"tot":56596},{"i":"151634","t":"多选","q":"中国特色社会主义法治道路本质上是中国特色社会主义道路在法治领域的具体体现，是推进社会主义法治建设的必由之路。中国特色社会主义法治道路的核心要义，就是要()","o":{"A":"A.坚持党的领导","B":"B.坚持统筹推进国内法治和涉外法治","C":"C.坚持中国特色社会主义制度","D":"D.贯彻中国特色社会主义法治理论"},"a":"ACD","j":"<p>中国特色社会主义法治道路本质上是中国特色社会主义道路在法治领域的具体体现，是推进社会主义法治建设的必由之路。<span style=\"color: #e03e2d;\">|</span>中国特色社会主义法治道路的<span style=\"background-color: #f8cac6; color: #000000;\">核心要义</span>，<strong>就是要</strong>()</p>\n<p>A.坚持党的领导&radic;</p>\n<p>B.坚持统筹推进国内法治和涉外法治<span style=\"background-color: #f8cac6; color: #000000;\">这是习近平法治思想主要内容之一，不合题意</span></p>\n<p>C.坚持中国特色社会主义制度&radic;</p>\n<p>D.贯彻中国特色社会主义法治理论&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">中国特色社会主义法治道路的核心要义，就是要坚持党的领导，坚持中国特色社会主义制度，贯彻中国特色社会主义法治理论。</span></p>","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":34808,"tot":57235},{"i":"151635","t":"多选","q":"依法治国、依法执政、依法行政是一个有机整体。关键在于党要坚持依法执政、各级政府要坚持依法行政。法治国家、法治政府、法治社会是相辅相成的，主要表现在()","o":{"A":"A.法治国家是法治建设的目标","B":"B.法治政府是建设法治国家的重点","C":"C.法治社会是构筑法治国家的基础","D":"D.法治社会建设是重点任务和主体工程"},"a":"ABC","j":"<p>依法治国、依法执政、依法行政是一个有机整体。关键在于党要坚持依法执政、各级政府要坚持依法行政。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">法治国家、法治政府、法治社会</span>是相辅相成的，<strong>主要表现在</strong>()</p>\n<p>A.法治国家是法治建设的目标&radic;</p>\n<p>B.法治政府是建设法治国家的重点&radic;</p>\n<p>C.法治社会是构筑法治国家的基础&radic;</p>\n<p>D.法治社会建设是<strong>重点任务和主体工程</strong><span style=\"background-color: #f8cac6; color: #000000;\">法治政府建设是重点任务和主体工程</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法治国家是法治建设的目标，法治政府是建设法治国家的重点，法治社会是构筑法治国家的基础。</span></p>","k":"考点38 建设法治中国","kid":"410","r":27758,"tot":58349},{"i":"151636","t":"多选","q":"现代国家会有很多规范，如宗教规范、道德规范、团体规范和行业规范等。法律至上要求这些规范都不得超越法律规范，都不得与法律规范相抵触。法律至上具体表现为()","o":{"A":"A.法律的普遍适用性","B":"B.法律的优先适用性","C":"C.法律的国家强制性","D":"D.法律的不可违抗性"},"a":"ABD","j":"<p>现代国家会有很多规范，如宗教规范、道德规范、团体规范和行业规范等。法律至上要求这些规范都不得超越法律规范，都不得与法律规范相抵触。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">法律至上</span><strong>具体表现为</strong>()</p>\n<p>A.法律的普遍适用性&radic;</p>\n<p>B.法律的优先适用性&radic;</p>\n<p>C.法律的国家强制性<span style=\"background-color: #f8cac6; color: #000000;\">这是法律的特征，不是法律至上的表现</span></p>\n<p>D.法律的不可违抗性&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法律至上具体表现为法律的普遍适用性，法律的优先适用性，法律的不可违抗性。</span></p>","k":"考点40 我国宪法的地位和基本原则","kid":"412","r":27651,"tot":58312},{"i":"151637","t":"多选","q":"法律义务是指反映一定的社会物质生活条件所制约的社会责任，是保障法律所规定的义务人应该按照权利人要求从事一定行为或不从事一定行为，以满足权利人利益的法律手段。法律义务的特点有()","o":{"A":"A.法律义务是历史的","B":"B.法律义务是稳定的","C":"C.法律义务可能发生变化","D":"D.法律义务源于现实需要"},"a":"ACD","j":"<p>法律义务是指反映一定的社会物质生活条件所制约的社会责任，是保障法律所规定的义务人应该按照权利人要求从事一定行为或不从事一定行为，以满足权利人利益的法律手段。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">法律义务的特点</span><strong>有</strong>()</p>\n<p>A.法律义务是历史的&radic;</p>\n<p>B.法律义务是<strong>稳定的</strong><span style=\"background-color: #f8cac6; color: #000000;\">法律义务可能发生变化</span></p>\n<p>C.法律义务可能发生变化&radic;</p>\n<p>D.法律义务源于现实需要&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法律义务是历史的，法律义务可能发生变化，法律义务源于现实需要。</span></p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":36499,"tot":56168},{"i":"151638","t":"多选","q":"我国政治权利共同构成了我国公民参与国家政治生活的重要保障，体现了我国民主制度的优越性和广泛性。我国公民具有的政治权利有()","o":{"A":"A.宗教信仰自由","B":"B.选举权","C":"C.表达权","D":"D.人身权利"},"a":"BC","j":"<p>我国政治权利共同构成了我国公民参与国家政治生活的重要保障，体现了我国民主制度的优越性和广泛性。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">我国公民具有的政治权利</span><strong>有</strong>()</p>\n<p>A.宗教信仰自由<span style=\"background-color: #f8cac6; color: #000000;\">这是宪法规定的公民其他基本权利，与政治权利并列</span></p>\n<p>B.选举权&radic;</p>\n<p>C.表达权&radic;</p>\n<p>D.人身权利<span style=\"background-color: #f8cac6; color: #000000;\">这是宪法规定的公民其他基本权利，与政治权利并列</span></p>\n<p>【答案】BC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">我国公民具有的政治权利有选举权、表达权民主管理权、监督权。</span></p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":24412,"tot":58787},{"i":"151640","t":"多选","q":"马克思指出：“你们的观念本身是资产阶级的生产关系和所有制关系的产物，正像你们的法不过是被奉为法律的你们这个阶级的意志一样，而这种意志的内容是由你们这个阶级的物质生活条件来决定的。”这说明在马克思看来，法律是()","o":{"A":"A.统治阶级全部意志的体现","B":"B.由社会物质生活条件所决定","C":"C.不是凭空出现的","D":"D.国家创制并保证实施的行为规范"},"a":"BC","j":"<p>马克思指出：&ldquo;你们的观念本身是<span style=\"background-color: #f8cac6; color: #000000;\">资产阶级的生产关系和所有制</span>关系的产物，正像你们的法不过是被奉为法律的你们这个<span style=\"background-color: #f8cac6; color: #000000;\">阶级的意志</span>一样，而<span style=\"background-color: #f8cac6; color: #000000;\">这种意志的内容</span>是由你们这个阶级的物质生活条件来<span style=\"background-color: #f8cac6; color: #000000;\">决定的</span>。&rdquo;<span style=\"color: #e03e2d;\">|</span>这说明在马克思看来，<span style=\"background-color: #f8cac6; color: #000000;\">法律</span><strong>是</strong>()</p>\n<p>A.统治阶级<strong>全部</strong>意志的体现<span style=\"background-color: #f8cac6; color: #000000;\">不是全部意志，而是整体意志、上升为国家意志的意志</span></p>\n<p>B.由社会物质生活条件所决定&radic;</p>\n<p>C.不是凭空出现的&radic;</p>\n<p>D.国家创制并保证实施的行为规范<span style=\"background-color: #f8cac6; color: #000000;\">未提及国家创制、强制力</span></p>\n<p>【答案】BC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">在马克思看来，法律由社会物质生活条件所决定，不是凭空出现的。</span></p>","k":"考点33 法律的含义及其历史发展","kid":"405","r":14264,"tot":62351},{"i":"151641","t":"多选","q":"习近平总书记强调，法治兴则民族兴，法治强则国家强。因此，我们要坚持走中国特色社会主义法治道路，更好推进中国特色社会主义法治体系建设。走中国特色社会主义法治道路，是因为它()","o":{"A":"A.是历史的必然结论","B":"B.是由我国社会主义国家性质所决定的","C":"C.是立足我国基本国情的必然选择","D":"D.坚持法律面前人人平等"},"a":"ABC","j":"<p>习近平总书记强调，法治兴则民族兴，法治强则国家强。因此，我们要坚持走中国特色社会主义法治道路，更好推进中国特色社会主义法治体系建设。<span style=\"color: #e03e2d;\">||</span>走<span style=\"background-color: #f8cac6; color: #000000;\">中国特色社会主义法治道路</span>，是<strong>因为它</strong>()</p>\n<p>A.是历史的必然结论&radic;</p>\n<p>B.是由我国社会主义国家性质所决定的&radic;</p>\n<p>C.是立足我国基本国情的必然选择&radic;</p>\n<p>D.坚持法律面前人人平等<span style=\"background-color: #f8cac6; color: #000000;\">这是中国特色社会主义法治道路的原则</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">走中国特色社会主义法治道路，是因为它是历史的必然结论，是由我国社会主义国家性质所决定的，是立足我国基本国情的必然选择。</span></p>","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":37481,"tot":56198},{"i":"151642","t":"多选","q":"坚持法律面前人人平等要求人人都严格依法办事，既充分享有法律规定的各项权利，又切实履行法律规定的各项义务，有利于维护法律权威、健全社会主义法治，确保实现全面依法治国的总目标。坚持法律面前人人平等的要求是()","o":{"A":"A.违法必究，一切违反宪法法律的行为都必须予以追究","B":"B.非歧视，即无差别对待","C":"C.坚持为了人民、依靠人民","D":"D.积极回应人民群众新要求新期待"},"a":"AB","j":"<p>坚持法律面前人人平等要求人人都严格依法办事，既充分享有法律规定的各项权利，又切实履行法律规定的各项义务，有利于维护法律权威、健全社会主义法治，确保实现全面依法治国的总目标。<span style=\"background-color: #f8cac6; color: #000000;\">坚持法律面前人人平等的要求</span><strong>是</strong>()</p>\n<p>A.违法必究，一切违反宪法法律的行为都必须予以追究&radic;</p>\n<p>B.非歧视，即无差别对待&radic;</p>\n<p>C.坚持为了人民、依靠人民</p>\n<p>D.积极回应人民群众新要求新期待</p>\n<p><span style=\"background-color: #f8cac6; color: #000000;\">CD 是坚持人民主体地位的要求</span></p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">坚持法律面前人人平等的要求是违法必究，一切违反宪法法律的行为都必须予以追究；非歧视，即无差别对待。</span></p>","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":27621,"tot":58350},{"i":"151643","t":"多选","q":"习近平总书记指出，国无德不兴，人无德不立。中华文明之所以能够经受住各种冲击而坚守根基，很重要的一条原因是法治和德治相结合的传统文化基因。关于“法治”与“德治”,表述正确的是()","o":{"A":"A.法治与德治都是促进社会发展必不可少的手段","B":"B.法治与德治都是治国理政的基本方式","C":"C.法治和德治对社会成员都具有约束作用","D":"D.法律规范和道德规范都具有必须遵守的性质"},"a":"ACD","j":"<p>习近平总书记指出，国无德不兴，人无德不立。中华文明之所以能够经受住各种冲击而坚守根基，很重要的一条原因是法治和德治相结合的传统文化基因。<span style=\"color: #e03e2d;\">|</span>关于<span style=\"background-color: #f8cac6; color: #000000;\">&ldquo;法治&rdquo;与&ldquo;德治&rdquo;</span>,<strong>表述正确的是</strong>()</p>\n<p>A.法治与德治都是促进社会发展必不可少的手段&radic;</p>\n<p>B.法治与德治都是<strong>治国理政的基本方式</strong><span style=\"background-color: #f8cac6; color: #000000;\">法治德治地位不同，只有法治是治国理政的基本方式</span></p>\n<p>C.法治和德治对社会成员都具有约束作用&radic;</p>\n<p>D.法律规范和道德规范都具有必须遵守的性质&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法治与德治都是促进社会发展必不可少的手段；法治和德治对社会成员都具有约束作用；法律规范和道德规范都具有必须遵守的性质，只是违反后后果不同。</span></p>","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":15611,"tot":60964},{"i":"151644","t":"多选","q":"1954年9月，中华人民共和国第一届全国人民代表大会第一次会议在北京召开。大会讨论并通过了《中华人民共和国宪法》,为巩固社会主义政权和进行社会主义建设发挥了重要保障和推动作用。宪法()","o":{"A":"A.具有根本性、全局性、稳定性、长期性","B":"B.是实现国家认同、凝聚社会共识、促进个人发展的基本准则","C":"C.是维系一个国家、一个民族凝聚力的根本纽带","D":"D.是法治社会的基础工程"},"a":"ABC","j":"<p>1954年9月，中华人民共和国第一届全国人民代表大会第一次会议在北京召开。大会讨论并通过了《中华人民共和国宪法》,为巩固社会主义政权和进行社会主义建设发挥了重要保障和推动作用。<strong>宪法</strong>()</p>\n<p>A.具有根本性、全局性、稳定性、长期性&radic;</p>\n<p>B.是实现国家认同、凝聚社会共识、促进个人发展的基本准则&radic;</p>\n<p>C.是维系一个国家、一个民族凝聚力的根本纽带&radic;</p>\n<p>D.是法治社会的基础工程<span style=\"background-color: #f8cac6; color: #000000;\">全民守法是法治社会的基础工程</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">宪法具有根本性、全局性、稳定性、长期性，是实现国家认同、凝聚社会共识、促进个人发展的基本准则，是维系一个国家、一个民族凝聚力的根本纽带。</span></p>","k":"考点40 我国宪法的地位和基本原则","kid":"412","r":21113,"tot":60375},{"i":"151645","t":"多选","q":"我国宪法是国家的根本法，是党和人民意志的集中体现，在全面依法治国中具有突出地位和重要作用。我国宪法至上地位体现在()","o":{"A":"A.宪法是国家各项制度和法律法规的总依据","B":"B.宪法是国家的根本法","C":"C.宪法体现了统治阶级的全部意志","D":"D.在中国特色社会主义法律体系中宪法居于核心地位"},"a":"ABD","j":"<p>我国宪法是国家的根本法，是党和人民意志的集中体现，在全面依法治国中具有突出地位和重要作用。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">我国宪法至上地位</span><strong>体现在</strong>()</p>\n<p>A.宪法是国家各项制度和法律法规的总依据&radic;</p>\n<p>B.宪法是国家的根本法&radic;</p>\n<p>C.宪法体现了统治阶级的<strong>全部意志</strong><span style=\"background-color: #f8cac6; color: #000000;\">上升为国家意志的意志和整体意志</span></p>\n<p>D.在中国特色社会主义法律体系中宪法居于核心地位&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">我国宪法至上地位体现在宪法是国家各项制度和法律法规的总依据，宪法是国家的根本法，在中国特色社会主义法律体系中宪法居于核心地位。</span></p>","k":"考点40 我国宪法的地位和基本原则","kid":"412","r":45530,"tot":54210},{"i":"151646","t":"多选","q":"法律权利和法律义务的关系，就像一枚硬币的两面，密不可分。在社会生活中，每个人既是享受法律权利的主体，又是承担法律义务的主体。二者之间关系的正确表述是()","o":{"A":"A.法律权利与法律义务具有二重性","B":"B.法律权利与法律义务是目的与手段的关系","C":"C.法律权利与法律义务具有顺序性","D":"D.法律权利与法律义务是相互依存的关系"},"a":"ABD","j":"<p>法律权利和法律义务的关系，就像一枚硬币的两面，密不可分。在社会生活中，每个人既是享受<span style=\"background-color: #f8cac6; color: #000000;\">法律权利</span>的主体，又是承担<span style=\"background-color: #f8cac6; color: #000000;\">法律义务</span>的主体。二者之间关系的<strong>正确表述</strong>是()</p>\n<p>A.法律权利与法律义务具有二重性&radic;</p>\n<p>B.法律权利与法律义务是目的与手段的关系&radic;</p>\n<p>C.法律权利与法律义务具有<strong>顺序性</strong><span style=\"background-color: #f8cac6; color: #000000;\">法律权利与法律义务是相伴而生的，无顺序性</span></p>\n<p>D.法律权利与法律义务是相互依存的关系&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法律权利与法律义务具有二重性，法律权利与法律义务是目的与手段的关系，法律权利与法律义务是相互依存的关系。</span></p>","k":"考点43 依法行使权利与履行义务","kid":"415","r":25347,"tot":58102},{"i":"151647","t":"多选","q":"有位法学家曾经说过：“法律必须被信仰，否则等于形同虚设。”这句话表明，一个人只有从内心深处真正认同、信任和信仰法律，才会自觉维护法律的权威。由此可见()","o":{"A":"A.法律的内在说服力是法律权威的内在基础","B":"B.法律权威不可能完全建立在外在强制力的基础之上","C":"C.法律信仰与宗教信仰没有本质的区别","D":"D.法律信仰是法律制定和执行的根本依据"},"a":"AB","j":"<p>有位法学家曾经说过：&ldquo;法律必须被信仰，否则等于形同虚设。&rdquo;这句话表明，<span style=\"background-color: #f8cac6; color: #000000;\">一个人只有从内心深处真正认同、信任和信仰法律，才会自觉维护法律的权威。</span><strong>由此可见</strong>()</p>\n<p>A.法律的内在说服力是法律权威的内在基础&radic;</p>\n<p>B.法律权威不可能完全建立在外在强制力的基础之上&radic;</p>\n<p>C.法律信仰与宗教信仰<strong>没有本质的区别</strong><span style=\"background-color: #f8cac6; color: #000000;\">明显常识错误</span></p>\n<p>D.<strong>法律信仰</strong>是法律<strong>制定和执行的根本依据</strong><span style=\"background-color: #f8cac6; color: #000000;\">第一梯队K对应错误</span></p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法律的内在说服力是法律权威的内在基础，法律权威不可能完全建立在外在强制力的基础之上。</span></p>","k":"考点44 不断提升法治素养","kid":"416","r":26901,"tot":58253},{"i":"151648","t":"多选","q":"我国社会主义法律，是在中国共产党领导新民主主义革命时期孕育、在中华人民共和国成立后不断形成和发展起来的。我国社会主义法律的特征包括","o":{"A":"A.具有科学性和先进性","B":"B.由一定的物质生活条件所决定","C":"C.体现了党的主张和人民意志的统一","D":"D.是中国特色社会主义建设的重要保障"},"a":"ACD","j":"<p>识记点A、C、D选项的说法&mdash;&mdash;是我国社会主义法律的特征，是本题正确答案。B选项的说法&mdash;&mdash;是法律的一般特征。</p>","k":"","kid":"","r":16897,"tot":61166},{"i":"151649","t":"多选","q":"1954年9月20日，中华人民共和国第一届全国人民代表大会第一次会议通过了《中华人民共和国宪法》。我国宪法同党和人民进行的艰苦奋斗和创造的辉煌成就紧密相连，同党和人民开辟的前进道路和积累的宝贵经验紧密相连。在我国，宪法是","o":{"A":"A.国家各项制度和法律法规的总依据","B":"B.维系一个国家、一个民族凝聚力的根本纽带","C":"C.党和人民意志的集中体现","D":"D.实现国家认同、凝聚社会共识、促进个人发展的基本准则"},"a":"ABCD","j":"识记点A、B、C、D选项的说法——是我国宪法的地位，是本题正确答案。","k":"","kid":"","r":37587,"tot":55987},{"i":"151650","t":"多选","q":"宪法的基本原则是贯穿宪法规范始终，对宪法的制定、修改、实施、遵守等环节起指导作用的基本准则。我国宪法的基本原则包括","o":{"A":"A.平等、自愿、公平原则","B":"B.人民当家作主原则","C":"C.党的领导原则","D":"D.尊重和保障人权原则"},"a":"BCD","j":"识记点A选项的说法——非考点。B、C、D选项的说法——是我国宪法的基本原则，是本题正确答案。此外，我国宪法的基本原则还包括社会主义法治原则、民主集中制原则。","k":"","kid":"","r":24150,"tot":58761},{"i":"151651","t":"多选","q":"法律至上是指在国家或社会的所有规范中，法律是地位最高、效力最广、强制力最大的规范。法律至上具体表现为法律的","o":{"A":"A.普遍适用","B":"B.优先适用","C":"C.不可违反","D":"D.公平普世"},"a":"ABC","j":"识记点A、B、C选项的说法——是法律至上的具体表现，是本题正确答案。D.公平普世——是错误说法。","k":"","kid":"","r":40796,"tot":54118},{"i":"151652","t":"多选","q":"公平正义是指社会的政治利益、经济利益和其他利益在全体社会成员之间合理、公平分配和占有。一般来讲，公平正义主要包括","o":{"A":"A.权力公平","B":"B.机会公平","C":"C.规则公平","D":"D.救济公平"},"a":"BCD","j":"<p>识记点A.<strong>权力公平</strong>&mdash;&mdash;<strong>是错误说法</strong>。B、C、D选项的说法&mdash;&mdash;是公平正义的内容，是本题正确答案。此外，公平正义还包括<strong>权利公平</strong>。</p>","k":"","kid":"","r":18504,"tot":60023},{"i":"151653","t":"多选","q":"权利公平包括多重含义，分别是","o":{"A":"A.权利主体平等","B":"B.享有的权利特别是基本权利平等","C":"C.权利保护和权利救济平等","D":"D.在法律内容面前人人平等"},"a":"ABC","j":"识记点A、B、C选项的说法——是权利公平的三重含义，是本题正确答案。D.在法律内容面前人人平等——是规则公平的内容。","k":"","kid":"","r":28952,"tot":57159},{"i":"151654","t":"多选","q":"机会公平是指生活在同一社会中的成员拥有相同的发展机会和发展前景，反对任何形式的歧视。它包括","o":{"A":"A.当代人和后代人的机会平等","B":"B.国家和社会要积极为社会成员的发展创造条件，并努力创造平等的起点","C":"C.社会成员的发展进步权要受到同等尊重","D":"D.为权利受到侵害或处于弱势地位的公民提供平等有效的救济"},"a":"ABC","j":"识记点A、B、C选项的说法——是机会公平的内容，是本题正确答案。D选项的说法——是救济公平的含义。","k":"","kid":"","r":20468,"tot":59044},{"i":"151655","t":"多选","q":"法律权利是指由一定的社会物质生活条件所制约的行为自由，是法律所允许的权利人为了满足自己的利益而采取的、由其他人的法律义务所保障的法律手段。法律权利的特征包括","o":{"A":"A.法律权利的内容、种类和实现程度受社会物质生活条件的制约","B":"B.法律权利的内容、分配和实现方式不因社会制度和国家法律的不同而存在差异","C":"C.法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性","D":"D.法律权利必须依法行使，不能不择手段地行使法律权利"},"a":"ACD","j":"<p>识记点A、C、D选项的说法&mdash;&mdash;是关于法律权利特征的正确表述，是本题正确答案。B选项的说法&mdash;&mdash;是错误说法，法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异，同样一种权利，在不同的社会制度下和不同的国家法律中表现形式有所不同。</p>","k":"","kid":"","r":23069,"tot":58268},{"i":"151656","t":"多选","q":"我国宪法法律规定了公民享有的一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。其中政治权利包括","o":{"A":"A.人身自由权","B":"B.民主管理权","C":"C.选举权与被选举权","D":"D.表达权"},"a":"BCD","j":"识记点A.人身自由权——是我国公民享有的人身权利之一。B、C、D选项的说法——是我国公民享有的政治权利，是本题正确答案。此外，我国公民享有的政治权利还包括监督权。","k":"","kid":"","r":26927,"tot":57700},{"i":"151657","t":"多选","q":"我国宪法法律规定了公民享有的一系列权利。其中，人身权利是指公民的人身不受非法侵犯的权利。它是公民参加国家政治、经济与社会生活的基础，是公民权利的重要内容。人身权利主要包括","o":{"A":"A.人格尊严权","B":"B.生命健康权","C":"C.通信自由权","D":"D.私有财产权"},"a":"ABC","j":"识记点A、B、C选项的说法——是我国公民享有的人身权利，是本题正确答案。此外，我国公民享有的人身权利还包括人身自由权、住宅安全权。D.私有财产权——是我国公民享有的财产权利之一。","k":"","kid":"","r":32387,"tot":56376},{"i":"151658","t":"多选","q":"社会经济权利，是指公民要求国家根据社会经济的发展状况，积极采取措施干预社会经济生活，加强社会建设，提供社会服务，以促进公民的自由和幸福，保障公民过上健康而有尊严的生活的权利。这一权利包括","o":{"A":"A.劳动权","B":"B.休息权","C":"C.私有财产权","D":"D.继承权"},"a":"AB","j":"识记点A、B选项的说法——是社会经济权利的内容，是本题正确答案。此外，社会经济权利还包括社会保障权、物质帮助权。C、D选项的说法——是财产权利的内容。","k":"","kid":"","r":29413,"tot":56783},{"i":"151659","t":"多选","q":"我国宪法规定了公民的宗教信仰自由，它是指公民依据内心的信念，自愿地信仰宗教的自由。具体内容包括","o":{"A":"A.信仰宗教的自由","B":"B.传播宗教信仰的自由","C":"C.从事宗教活动的自由","D":"D.举行或参加宗教仪式的自由"},"a":"ACD","j":"识记点A、C、D选项的说法——是宗教信仰自由的具体内容，是本题正确答案。B.传播宗教信仰的自由——不是我国宪法规定的公民宗教信仰自由的具体内容。","k":"","kid":"","r":30219,"tot":56743},{"i":"151660","t":"多选","q":"我国宪法第五十二条规定：中华人民共和国公民有维护国家统一和全国各民族团结的义务。可见，维护国家统一具有重大的意义，包括","o":{"A":"A.国家统一是公民实现法律权利与自由的前提","B":"B.维护国家统一是以宪法为核心的整个法律制度存在的基础","C":"C.维护国家统一是整个社会共同体存在和发展的基础","D":"D.国家统一是国家政权稳定和公民依法行使权利与自由的根本保障"},"a":"ABC","j":"<p>识记点A、B、C选项的说法&mdash;&mdash;是维护国家统一的意义，是本题正确答案。D选项的说法&mdash;&mdash;是错误说法，国家安全是国家政权稳定和公民依法行使权利与自由的根本保障。</p>","k":"","kid":"","r":13496,"tot":61075}]};
